def hazard_window(frame: pd.DataFrame, column: str, threshold: float, sector: str, lead_slots: int):
    part = frame[frame["Sector"] == sector] if not frame.empty else frame
    if part.empty or column not in part:
        return None
    active_times = []
    for slot in timeline_str:
        slot_df = part[part["Time"] == slot]
        if not slot_df.empty and safe_max(slot_df[column]) >= threshold:
            active_times.append(slot)
    if not active_times:
        return None
    start_index = timeline_str.index(active_times[0])
    if start_index > lead_slots:
        return None
    run = [active_times[0]]
    previous = start_index
    for slot in active_times[1:]:
        current = timeline_str.index(slot)
        if current == previous + 1:
            run.append(slot)
            previous = current
        else:
            break
    peak_slot = max(run, key=lambda slot: safe_max(part[part["Time"] == slot][column]))
    peak_df = part[part["Time"] == peak_slot].sort_values(column, ascending=False)
    stations = peak_df[peak_df[column] >= threshold]["Station"].head(4).tolist()
    if not stations:
        return None
    joiner = "، " if st.session_state.get("lang") != "en" else ", "
    window = part[part["Time"].isin(run)]
    direction = int(safe_max(peak_df["Wind Dir"])) if "Wind Dir" in peak_df else 0
    wind_min = float(window["Wind"].min()) if "Wind" in window else 0
    wind_max = float(window["Wind"].max()) if "Wind" in window else 0
    fog = safe_max(window["Fog Probability"]) if "Fog Probability" in window else 0
    dust = safe_max(window["Shamal Index"]) if "Shamal Index" in window else 0
    rain = safe_max(window["Drizzle Prob"]) if "Drizzle Prob" in window else 0
    storm = safe_max(window["Storm Probability"]) if "Storm Probability" in window else 0
    if fog >= 70:
        vis = 200
    elif fog >= 50:
        vis = 800
    elif storm >= 60:
        vis = 1500
    elif dust >= 60:
        vis = 2000
    elif rain >= 60:
        vis = 3000
    else:
        vis = 8000
    return run[0], run[-1], int(safe_max(peak_df[column])), joiner.join(stations), start_index == 0, direction, wind_min, wind_max, vis


def rain_words(level: int) -> str:
    if level >= 75:
        return tr("غزيرة", "heavy")
    if level >= 60:
        return tr("متوسطة", "moderate")
    return tr("خفيفة", "light")


