            chosen = st.session_state.get("forecast_hour") == hour
            mark = "● " if chosen else ""
            if col.button(f"{mark}{hour}", key=f"time_{st.session_state.forecast_day}_{hour}", use_container_width=True):
                st.session_state.forecast_hour = hour
